
DOCUMENTS = [
    {"id": "doc1", "title": "The Hippocampus and Memory", "content": "The Hippocampus is a complex brain structure embedded deep into temporal lobe. It has a major role in learning and memory. It is connected to the Prefrontal Cortex."},
    {"id": "doc2", "title": "The Prefrontal Cortex", "content": "The Prefrontal Cortex covers the front part of the frontal lobe. It is implicated in planning complex cognitive behavior, personality expression, and decision-making."},
    {"id": "doc3", "title": "Amygdala and Emotion", "content": "The Amygdala is an almond-shaped mass of gray matter inside each cerebral hemisphere. It is involved with the experiencing of emotions. It has strong connections to the Hippocampus."},
    {"id": "doc4", "title": "Cerebellum Motor Control", "content": "The Cerebellum receives information from the sensory systems and regulates motor movements. It coordinates voluntary movements such as posture and balance."},
    {"id": "doc5", "title": "Thalamus as a Relay", "content": "The Thalamus is a small structure within the brain located just above the brain stem. Its primary function is to relay motor and sensory signals to the cerebral cortex."},
    {"id": "doc6", "title": "Visual Cortex V1", "content": "The Visual Cortex (V1) is located in the occipital lobe. It receives sensory input from the eyes through the lateral geniculate nucleus in the Thalamus."},
    {"id": "doc7", "title": "Motor Cortex Functions", "content": "The Motor Cortex is the region of the cerebral cortex involved in the planning, control, and execution of voluntary movements. It sends signals via the Corticospinal Tract."},
    {"id": "doc8", "title": "Broca's Area", "content": "Broca's Area is a region in the frontal lobe of the dominant hemisphere, usually the left, with functions linked to speech production. Damage can cause Broca's aphasia."},
    {"id": "doc9", "title": "Wernicke's Area", "content": "Wernicke's Area is located in the temporal lobe on the left side of the brain and is responsible for the comprehension of speech. Damage here causes Wernicke's aphasia."},
    {"id": "doc10", "title": "Basal Ganglia", "content": "The Basal Ganglia are a group of subcortical nuclei responsible primarily for motor control, as well as other roles such as motor learning and emotions. Degeneration of the Substantia Nigra here leads to Parkinson's disease."},
    {"id": "doc11", "title": "Hypothalamus", "content": "The Hypothalamus is located below the Thalamus. It links the nervous system to the endocrine system via the pituitary gland."},
    {"id": "doc12", "title": "Insular Cortex", "content": "The Insular Cortex is a portion of the cerebral cortex folded deep within the lateral sulcus. It is believed to be involved in consciousness and plays a role in diverse functions usually linked to emotion or the regulation of the body's homeostasis."},
    {"id": "doc13", "title": "Anterior Cingulate Cortex", "content": "The Anterior Cingulate Cortex is the frontal part of the cingulate cortex. It appears to play a role in a wide variety of autonomic functions, such as regulating blood pressure and heart rate."},
    {"id": "doc14", "title": "Entorhinal Cortex", "content": "The Entorhinal Cortex is an area of the brain located in the medial temporal lobe and functions as a hub in a widespread network for memory and navigation."},
    {"id": "doc15", "title": "Substantia Nigra", "content": "The Substantia Nigra is a basal ganglia structure located in the midbrain that plays an important role in reward and movement. Loss of dopaminergic neurons here is the primary cause of Parkinson's disease."},
    {"id": "doc16", "title": "Fornix", "content": "The Fornix is a C-shaped bundle of nerve fibers in the brain that acts as the major output tract of the hippocampus. It carries signals from the hippocampus to the mammillary bodies and then to the anterior nuclei of thalamus."},
    {"id": "doc17", "title": "Uncinate Fasciculus", "content": "The Uncinate Fasciculus is a white matter tract in the human brain that connects parts of the limbic system such as the hippocampus and amygdala with the frontal ones such as the orbitofrontal cortex."},
    {"id": "doc18", "title": "Arcuate Fasciculus", "content": "The Arcuate Fasciculus is a bundle of axons that forms part of the superior longitudinal fasciculus. It bidirectionally connects caudal temporal cortex and inferior parietal cortex to locations in the frontal lobe, linking Wernicke's Area to Broca's Area."},
    {"id": "doc19", "title": "Corpus Callosum", "content": "The Corpus Callosum is a large, C-shaped nerve fiber bundle found beneath the cerebral cortex. It stretches across the midline of the brain, connecting the left and right cerebral hemispheres."},
    {"id": "doc20", "title": "Corticospinal Tract", "content": "The Corticospinal Tract is a white matter motor pathway starting at the cerebral cortex that terminates on lower motor neurons and interneurons in the spinal cord, controlling movements of the limbs and trunk."},
    {"id": "doc21", "title": "Alzheimer's Disease", "content": "Alzheimer's disease is a neurodegenerative disease that usually starts slowly and progressively worsens. It is the cause of 60-70% of cases of dementia. It typically begins in the Entorhinal Cortex and Hippocampus."},
    {"id": "doc22", "title": "Parkinson's Disease", "content": "Parkinson's disease is a long-term degenerative disorder of the central nervous system that mainly affects the motor system. It is caused by the death of cells in the Substantia Nigra."},
    {"id": "doc23", "title": "PTSD", "content": "Post-traumatic stress disorder (PTSD) is a mental disorder that can develop after a person is exposed to a traumatic event. It often involves hyperactivity in the Amygdala and changes in the Prefrontal Cortex and Hippocampus."},
    {"id": "doc24", "title": "Broca's Aphasia", "content": "Broca's aphasia, also known as expressive aphasia, is a type of aphasia characterized by partial loss of the ability to produce language, although comprehension generally remains intact. It is caused by damage to Broca's Area."},
    {"id": "doc25", "title": "Wernicke's Aphasia", "content": "Wernicke's aphasia, also known as receptive aphasia, is a type of aphasia in which individuals have difficulty understanding written and spoken language. It is caused by damage to Wernicke's Area."},
]
